/**
 * A per-thread display alias. Random, not derived from the account, so two
 * aliases in different threads cannot be linked back to one member (PRIV-02).
 */
export function randomAlias(): string {
  const adjective = ALIAS_ADJECTIVES[Math.floor(Math.random() * ALIAS_ADJECTIVES.length)]
  const noun = ALIAS_NOUNS[Math.floor(Math.random() * ALIAS_NOUNS.length)]
  const suffix = Math.floor(Math.random() * 900 + 100)
  return `${adjective} ${noun} ${suffix}`
}

/** A trade nickname suggestion for a new market profile. */
export function suggestNickname(): string {
  const noun = ALIAS_NOUNS[Math.floor(Math.random() * ALIAS_NOUNS.length)]
  return `${noun}${Math.floor(Math.random() * 9000 + 1000)}`
}

/**
 * Extra digits for a nickname that keeps colliding. The first suggestions draw
 * from four digits, which is pleasant to read and runs out; this widens the
 * space without making every nickname ugly.
 */
export function randomDigits(count: number): string {
  let out = ''
  for (let i = 0; i < count; i++) out += String(Math.floor(Math.random() * 10))
  return out
}

/**
 * Picks the Korean particle that fits the word in front of it.
 *
 * Writing "이(가)" and letting the reader sort it out marks a sentence as
 * machine output, which is the opposite of what an automated post needs.
 *
 * A Hangul syllable encodes its final consonant in its code point: subtract
 * the block start and a remainder of zero means there is none. Trailing
 * brackets, quotes and punctuation are skipped, because a filing name ends
 * ")" or "」" far more often than it ends in a syllable and the particle
 * belongs to the last word, not to the bracket.
 */
export function koreanParticle(word: string, withFinal: string, withoutFinal: string): string {
  for (const char of [...word.trim()].reverse()) {
    const code = char.codePointAt(0) ?? 0
    if (code >= 0xac00 && code <= 0xd7a3) {
      return (code - 0xac00) % 28 === 0 ? withoutFinal : withFinal
    }
    // Digits read aloud in Korean, so they decide the particle themselves.
    if (char >= '0' && char <= '9') {
      // 1, 3, 6, 7, 8, 0 end in a consonant when spoken (일 삼 육 칠 팔 영).
      return '136780'.includes(char) ? withFinal : withoutFinal
    }
  }
  return withoutFinal
}

/** Korean-aware character count (code points, not UTF-16 units). */
export function charCount(text: string): number {
  return [...text].length
}

/** Hash-friendly client fingerprint fragments; never stored raw (SEC-05). */
export function clientIpFrom(request: Request, trustProxy: boolean): string {
  if (!trustProxy) return ''
  const headers = request.headers
  return (
    headers.get('cf-connecting-ip') ??
    headers.get('x-real-ip') ??
    (headers.get('x-forwarded-for') ?? '').split(',')[0]?.trim() ??
    ''
  )
}
