 * so without this the server answers "who am I" with whichever cookie it
 * happens to check first.
 */
export const SESSION_HINT_HEADER = 'x-insight-session'

function isAdminSurface(): boolean {
  return window.location.pathname.startsWith('/admin')
}

type Listener = (error: ApiError) => void
const unauthenticatedListeners = new Set<Listener>()

/**
 * Notified when any call comes back unauthenticated, so the shell can move to
 * the sign-in screen once instead of every screen handling it.
 */
export function onUnauthenticated(listener: Listener): () => void {
  unauthenticatedListeners.add(listener)
  return () => unauthenticatedListeners.delete(listener)
}

function readCookie(name: string): string {
  for (const part of document.cookie.split(';')) {
    const eq = part.indexOf('=')
    if (eq <= 0) continue
    if (part.slice(0, eq).trim() === name) {
      try {
        return decodeURIComponent(part.slice(eq + 1).trim())
      } catch {
        return ''
      }
    }
  }
  return ''
}

/** The admin console has its own session, so it echoes its own token. */
function csrfToken(): string {
  const admin = isAdminSurface()
  return readCookie(admin ? 'yi_acsrf' : 'yi_csrf')
