 * headers as any write, the body saved under the server's file name.
 */
async function download(path: string, payload: unknown, fallbackName: string): Promise<void> {
  const headers: Record<string, string> = { 'content-type': 'application/json' }
  if (isAdminSurface()) headers[SESSION_HINT_HEADER] = 'admin'
  const token = csrfToken()
  if (token) headers[CSRF_HEADER] = token
  const response = await fetch(path, { method: 'POST', headers, body: JSON.stringify(payload ?? {}), credentials: 'same-origin' })
  if (!response.ok) {
    const envelope = (await response.json().catch(() => ({}))) as { error?: { code?: string; message?: string } }
    throw new ApiError({ status: response.status, code: envelope.error?.code ?? String(response.status), message: envelope.error?.message ?? defaultMessage(response.status) })
  }
  const name = /filename="([^"]+)"/.exec(response.headers.get('content-disposition') ?? '')?.[1] ?? fallbackName
  const url = URL.createObjectURL(await response.blob())
  const link = document.createElement('a')
  link.href = url
  link.download = name
  document.body.appendChild(link)
  link.click()
  link.remove()
  window.setTimeout(() => URL.revokeObjectURL(url), 10_000)
}

