//
// The ledger is public.insight_schema_migrations, not schema_migrations: this
// service can share a Postgres instance with yeopjari (its schemas are `insight`
// and `insight_priv`), and the two must never read each other's ledger.
//
//   DATABASE_URL=postgres://... node scripts/migrate.mjs
//   DATABASE_URL=... INSIGHT_APP_DB_PASSWORD=... node scripts/migrate.mjs
//
// The optional app password gives the restricted insight_app role a login, so
// the BFF can connect as the role the RLS policies are written against.
import { readFile, readdir } from 'node:fs/promises'
